package com.shazwan.idash;
import android.app.*;import android.content.*;import android.media.session.*;import android.os.*;import android.view.*;import java.io.*;
/** Disposable API27 fixture; restores access/filter and stops separate-UID session fixture. */
public class MediaUtilitiesChecks extends Instrumentation {
 LauncherActivity a;int count;NotificationManager notification;int originalFilter;boolean policy;long filterWaitMs;
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);count++;}
 void ui(Runnable work){Throwable[] fail={null};runOnMainSync(()->{try{work.run();}catch(Throwable t){fail[0]=t;}});waitForIdleSync();if(fail[0]!=null)throw new AssertionError(fail[0]);}
 void shell(String command)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(command);InputStream in=new FileInputStream(fd.getFileDescriptor())){byte[] b=new byte[2048];while(in.read(b)!=-1){}}}
 void waitTitle(String text)throws Exception{long end=SystemClock.elapsedRealtime()+12000;while(SystemClock.elapsedRealtime()<end){if(a.quickControls.mediaControl.title.getText().toString().contains(text))return;Thread.sleep(100);}throw new AssertionError("Media title missing: "+text);}
 void waitState(int state)throws Exception{long end=SystemClock.elapsedRealtime()+10000;while(SystemClock.elapsedRealtime()<end){MediaController c=a.quickControls.mediaControl.controller;if(c!=null&&c.getPlaybackState()!=null&&c.getPlaybackState().getState()==state)return;Thread.sleep(100);}throw new AssertionError("Playback callback state "+state);}
 void waitFilter(int expected)throws Exception{long start=SystemClock.elapsedRealtime(),end=start+10000;int actual;while((actual=notification.getCurrentInterruptionFilter())!=expected&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);filterWaitMs=SystemClock.elapsedRealtime()-start;check(actual==expected,"Focus changes real DND after explicit selection; actual="+actual+", waited="+filterWaitMs+"ms");}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
  shell("am force-stop dev.idash.mediafixture");shell("cmd notification disallow_listener com.shazwan.idash/.MediaAccessService");shell("cmd notification disallow_dnd com.shazwan.idash");
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();java.util.concurrent.CountDownLatch catalog=new java.util.concurrent.CountDownLatch(1);a.worker.execute(()->a.main.post(catalog::countDown));check(catalog.await(45,java.util.concurrent.TimeUnit.SECONDS),"app discovery ready for utility fallback");waitForIdleSync();ui(a::controlCenter);final ControlMedia media=a.quickControls.mediaControl;ControlUtilities utilities=a.quickControls.utilitiesControl;ui(utilities::resolveApps);
  ui(()->{check(!media.granted(),"media permission denied");check(media.title.getText().toString().contains("access"),"denial distinct from Not Playing");check(!media.play.isEnabled()&&!media.next.isEnabled()&&!media.previous.isEnabled(),"denied transport disabled");check(!utilities.policyGranted(),"DND permission denied");});
  notification=(NotificationManager)a.getSystemService(Context.NOTIFICATION_SERVICE);originalFilter=notification.getCurrentInterruptionFilter();ui(utilities::focus);check(notification.getCurrentInterruptionFilter()==originalFilter,"opening Focus without access does not alter DND");ui(()->utilities.prompt.dismiss());
  shell("cmd notification allow_listener com.shazwan.idash/.MediaAccessService");long end=SystemClock.elapsedRealtime()+12000;while(!media.granted()&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);ui(media::reload);ui(()->{check(media.granted(),"listener access granted");check(media.controller==null,"no active session state");check("Not Playing".contentEquals(media.title.getText()),"empty state after permission granted");});
  shell("am start -W -n dev.idash.mediafixture/.Main");shell("am start -W -n com.shazwan.idash/.LauncherActivity");ui(()->{if(a.quickControls.dialog==null||!a.quickControls.dialog.isShowing())a.controlCenter();a.quickControls.resume();});final ControlMedia live=a.quickControls.mediaControl;
  waitTitle("Fixture track one");ui(()->{check("dev.idash.mediafixture".equals(live.controller.getPackageName()),"actual separate-UID session selected");check(live.play.isEnabled()&&live.next.isEnabled()&&live.previous.isEnabled(),"supported session actions enabled");live.play.performClick();});waitState(PlaybackState.STATE_PAUSED);check(true,"Pause callback reaches media fixture");ui(()->live.play.performClick());waitState(PlaybackState.STATE_PLAYING);check(true,"Play callback reaches media fixture");ui(()->live.next.performClick());waitTitle("Fixture track two");check(true,"Next updates metadata via callback");ui(()->live.previous.performClick());waitTitle("Fixture track one");check(true,"Previous updates metadata via callback");
  shell("am start -W -n dev.idash.mediafixture/.Main --ez toggleOnly true");shell("am start -W -n com.shazwan.idash/.LauncherActivity");ui(()->{a.quickControls.resume();live.reload();});ui(()->{check(!live.previous.isEnabled()&&!live.next.isEnabled()&&live.play.isEnabled(),"action mask disables unsupported transport");live.play.performClick();});waitState(PlaybackState.STATE_PAUSED);check(true,"toggle-only action dispatches supported media button");ui(()->live.play.performClick());waitState(PlaybackState.STATE_PLAYING);
  shell("cmd notification allow_dnd com.shazwan.idash");policy=true;ui(()->{check(utilities.policyGranted(),"DND access granted");utilities.focus();});ui(()->utilities.prompt.getListView().performItemClick(null,1,1));waitFilter(NotificationManager.INTERRUPTION_FILTER_PRIORITY);
  android.graphics.Bitmap screen=getUiAutomation().takeScreenshot();if(screen!=null){try(java.io.OutputStream out=new java.io.FileOutputStream(new java.io.File(a.getFilesDir(),"media-control-center.png"))){screen.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}screen.recycle();}
  ui(()->{a.quickControls.pause();check(!live.active&&!live.listening&&!utilities.active,"pause releases media/session/utility callbacks");a.quickControls.resume();check(live.active&&!utilities.active,"resume reattaches media without removed utility listeners");});
  shell("am force-stop dev.idash.mediafixture");ui(live::reload);waitTitle("Not Playing");check(true,"destroyed session restores empty state");
  ui(()->{ControlUtilities current=a.quickControls.utilitiesControl;check(current.focus==null&&current.buttons[0]==null&&current.buttons[1]==null&&current.buttons[2]==null,"utilities removed only from Control Center UI");current.launch(null);check(true,"missing utility intent handled");check(!ControlMedia.supports(PlaybackState.ACTION_PLAY,PlaybackState.ACTION_SKIP_TO_NEXT),"unsupported media action rejected");});
  shell("cmd notification disallow_listener com.shazwan.idash/.MediaAccessService");ui(live::reload);ui(()->check(!live.granted()&&live.title.getText().toString().contains("access")&&!live.play.isEnabled(),"revocation returns access-needed state"));
  for(Intent utility:new Intent[]{utilities.timer,utilities.calculator})if(utility!=null){runOnMainSync(()->utilities.launch(utility));long deadline=SystemClock.elapsedRealtime()+12000;while(a.resumed&&SystemClock.elapsedRealtime()<deadline)Thread.sleep(100);check(!a.resumed,"resolved utility launches external Activity: "+utility.getAction());shell("am start -W -n com.shazwan.idash/.LauncherActivity");ui(()->{a.quickControls.resume();check(a.resumed&&live.active&&!utilities.active,"return from utility restores media lifecycle without utility UI");});}
  result.putString("stream","PASS: "+count+" media/utility assertions\nDND filter observed after "+filterWaitMs+"ms; bounded public-API wait off the UI thread.\n");code=Activity.RESULT_OK;
 }catch(Throwable t){result.putString("stream","FAIL after "+count+": "+t+"\n");}finally{try{if(policy&&notification!=null)notification.setInterruptionFilter(originalFilter);shell("am force-stop dev.idash.mediafixture");shell("cmd notification disallow_listener com.shazwan.idash/.MediaAccessService");shell("cmd notification disallow_dnd com.shazwan.idash");}catch(Exception ignored){}if(a!=null)runOnMainSync(()->{if(a.quickControls!=null)a.quickControls.close();a.finish();});}finish(code,result);}

}
